//! `BRepFill_Evolved::ElementaryPerform` (`BRepFill_Evolved.cxx:657-1265`):
//! builds the elementary evolved volumes of one profile wire on one side of
//! the bisecting locus - tubes along the spine edges, revolutions around the
//! vertical axes, the edges generated by the bisectrices, the parallel edges
//! on the vertices of the profile, and finally the cut faces.

use occt_core::gp::{GpAx3, GpDir, GpPnt};
use occt_core::kernel::geomabs::Shape;

use crate::abs::{Orientation, ShapeType};
use crate::brep_fill_offset_wire::vertices::update_vertex_point;
use crate::brep_fill_trim_surface_tool::TrimSurfaceTool;
use crate::brep_mat2d_bisecting_locus::BRepMat2dBisectingLocus;
use crate::brep_mat2d_link_topo_bilo::BRepMat2dLinkTopoBilo;
use crate::brep_tool::BRepTool;
use crate::brep_tools::ori_edge_in_face;
use crate::brep_tools_wire_explorer::WireExplorer;
use crate::builder::TopoBuilder;
use crate::shape::{Edge, Face, TopoShape, Vertex, Wire};
use crate::tgeometry::GeometryRegistry;
use crate::topo_tools::{vertices_of, wires_of_face};

use super::evolved::BRepFillEvolved;
use super::intervals::{compute_intervals, vertex_from_node, MapNodeVertex};
use super::shape_map::ShapeMap;
use super::side::{
    concave_side, distance_to_oz, edge_vertices_oriented, simple_expression, FILL_CONFUSION,
};
use super::trim_edge::trim_edge;
use super::trim_face::trim_face;

/// `IsInversed(S, E1, E2, Inverse)` (`BRepFill_Evolved.cxx:548-610`):
/// whether the tangent of `S` at its oriented end runs against the tangents of
/// `E1` / `E2` at their oriented ends.
fn is_inversed(s: &TopoShape, e1: &Edge, e2: &Edge, inverse: &mut [bool; 2]) {
    inverse[0] = false;
    inverse[1] = false;
    // `cxx:555-558`.
    if s.shape_type() != ShapeType::Edge {
        return;
    }
    let edge = Edge(s.clone());
    let Some(curve) = BRepTool::edge_curve(&edge) else {
        return;
    };
    let (first, last) = BRepTool::edge_parameters(&edge);
    // `cxx:562-571`.
    let ds = if s.orientation() == Orientation::Forward {
        curve.d1(first).1
    } else {
        curve.d1(last).1.reversed()
    };

    // `cxx:573-590`.
    if !BRepTool::is_degenerated(e1) {
        if let Some(c1) = BRepTool::edge_curve(e1) {
            let (f1, l1) = BRepTool::edge_parameters(e1);
            let dc1 = if e1.0.orientation() == Orientation::Forward {
                c1.d1(f1).1
            } else {
                c1.d1(l1).1.reversed()
            };
            inverse[0] = ds.dot(&dc1) < 0.0;
        }
    } else {
        inverse[0] = true;
    }

    // `cxx:592-609`.
    if !BRepTool::is_degenerated(e2) {
        if let Some(c2) = BRepTool::edge_curve(e2) {
            let (f2, l2) = BRepTool::edge_parameters(e2);
            let dc2 = if e2.0.orientation() == Orientation::Forward {
                c2.d1(f2).1
            } else {
                c2.d1(l2).1.reversed()
            };
            inverse[1] = ds.dot(&dc2) < 0.0;
        }
    } else {
        inverse[1] = true;
    }
}

/// `myMap(A)(B).First()` (`cxx:777`): the first recorded shape.
fn first_of(my_map: &ShapeMap<ShapeMap<Vec<TopoShape>>>, a: &TopoShape, b: &TopoShape) -> Option<TopoShape> {
    my_map.list(a, b).and_then(|l| l.first().cloned())
}

impl BRepFillEvolved {
    /// `ElementaryPerform(Sp, Pr, Locus, Link, Join)`
    /// (`BRepFill_Evolved.cxx:657-1265`).
    ///
    /// `Join` is unused by the reference (`cxx:661`), which only accepts
    /// `GeomAbs_Arc` before reaching here (`cxx:349-352`).
    pub fn elementary_perform(
        &mut self,
        sp: &Face,
        pr: &Wire,
        locus: &BRepMat2dBisectingLocus,
        link: &mut BRepMat2dLinkTopoBilo,
    ) -> Result<(), String> {
        // `cxx:665-673`. `myProfile = Pr` keeps the wire as given (no
        // `Oriented` copy, unlike the spine).
        self.my_spine = Some(Face(sp.0.oriented(Orientation::Forward)));
        self.my_profile = Some(pr.clone());
        self.my_map.clear();

        let builder = TopoBuilder::new();
        let registry = GeometryRegistry::global();
        // `cxx:670-671`: `myBuilder.MakeCompound(myShape)`.
        self.my_shape = Some(builder.make_compound_of(&[]).0);

        let my_spine = self.my_spine.clone().expect("spine was just set");
        let my_profile = self.my_profile.clone().expect("profile was just set");

        // `cxx:698`: the reference frame of the profile, `yOz`.
        let axe_ref = GpAx3::from_point_dir_x(
            GpPnt::new(0.0, 0.0, 0.0),
            GpDir::new(0.0, 0.0, 1.0).expect("gp::DZ"),
            &GpDir::new(1.0, 0.0, 0.0).expect("gp::DX"),
        )
        .map_err(|e| e.to_string())?;

        let mut map_node_vertex: MapNodeVertex = MapNodeVertex::new();

        // `cxx:709-746`: revolutions and tubes.
        for wire in wires_of_face(&my_spine) {
            let mut wire_exp = WireExplorer::new();
            wire_exp.init(&wire, None);
            while wire_exp.more() {
                let Some(current_edge) = wire_exp.current().cloned() else {
                    break;
                };
                let (_, v_last) = edge_vertices_oriented(&current_edge);

                // `cxx:719-723`: one revolution per basic element linked to
                // the last vertex.
                if let Some(v_last) = v_last.as_ref() {
                    link.init(&v_last.0);
                    let mut count = 0;
                    while link.more() {
                        link.next();
                        count += 1;
                    }
                    for _ in 0..count {
                        self.make_revol(&current_edge, v_last, &axe_ref)?;
                    }
                }

                // `cxx:725-731`: one tube per basic element linked to the
                // edge.
                link.init(&current_edge.0);
                let mut count = 0;
                while link.more() {
                    link.next();
                    count += 1;
                }
                for _ in 0..count {
                    self.make_pipe(&current_edge, &axe_ref)?;
                }

                wire_exp.next();
            }
        }

        // `cxx:750-1265`: the bisectrices.
        let graph = locus.graph();
        let mut map_bis: ShapeMap<Vec<TopoShape>> = ShapeMap::new();
        let mut map_ver_par: ShapeMap<Vec<f64>> = ShapeMap::new();
        let mut map_seq_ver: ShapeMap<Vec<TopoShape>> = ShapeMap::new();
        let mut map_seq_par: ShapeMap<Vec<GpPnt>> = ShapeMap::new();

        for i in 1..=graph.number_of_arcs() {
            let arc_id = graph.arc(i);
            let arc = graph.arc_by_id(arc_id);
            let mut reverse = false;
            let bis_bisec = locus.geom_bis(arc, &mut reverse);
            let Some(bis_curve) = bis_bisec.value() else {
                return Err("BRepFill_Evolved: bisector without a curve".into());
            };
            let bis = simple_expression(bis_curve);

            // `cxx:758-759`.
            let s0 = link.generating_shape(
                arc.first_element()
                    .ok_or_else(|| "BRepFill_Evolved: arc without first element".to_string())?,
            );
            let s1 = link.generating_shape(
                arc.second_element()
                    .ok_or_else(|| "BRepFill_Evolved: arc without second element".to_string())?,
            );

            // `cxx:761-762`.
            let concave0 = concave_side(&s0, &my_spine);
            let concave1 = concave_side(&s1, &my_spine);

            let mut v_on_f: Vec<TopoShape> = Vec::new();
            let mut v_on_l: Vec<TopoShape> = Vec::new();
            let mut par_on_f: Vec<GpPnt> = Vec::new();
            let mut par_on_l: Vec<GpPnt> = Vec::new();

            // `cxx:771`.
            let mut prof_exp = WireExplorer::new();
            prof_exp.init(&my_profile, None);
            while prof_exp.more() {
                let Some(prof_edge) = prof_exp.current().cloned() else {
                    break;
                };

                // `cxx:777-778`.
                let f0 = Face(
                    first_of(&self.my_map, &s0, &prof_edge.0)
                        .ok_or_else(|| "BRepFill_Evolved: no face for S[0]".to_string())?,
                );
                let f1 = Face(
                    first_of(&self.my_map, &s1, &prof_edge.0)
                        .ok_or_else(|| "BRepFill_Evolved: no face for S[1]".to_string())?,
                );

                // `cxx:782-790`.
                let (vf, vl) = edge_vertices_oriented(&prof_edge);
                let (Some(vf), Some(vl)) = (vf, vl) else {
                    prof_exp.next();
                    continue;
                };
                let e0 = Edge(
                    first_of(&self.my_map, &s0, &vf.0)
                        .ok_or_else(|| "BRepFill_Evolved: no edge on VF (S[0])".to_string())?,
                );
                let e1 = Edge(
                    first_of(&self.my_map, &s0, &vl.0)
                        .ok_or_else(|| "BRepFill_Evolved: no edge on VL (S[0])".to_string())?,
                );
                let e2 = Edge(
                    first_of(&self.my_map, &s1, &vf.0)
                        .ok_or_else(|| "BRepFill_Evolved: no edge on VF (S[1])".to_string())?,
                );
                let e3 = Edge(
                    first_of(&self.my_map, &s1, &vl.0)
                        .ok_or_else(|| "BRepFill_Evolved: no edge on VL (S[1])".to_string())?,
                );

                // `cxx:795-803`.
                let mut inv0 = [false; 2];
                let mut inv1 = [false; 2];
                if concave0 {
                    is_inversed(&s0, &e0, &e1, &mut inv0);
                }
                if concave1 {
                    is_inversed(&s1, &e2, &e3, &mut inv1);
                }

                // `cxx:808`: `BRepFill_TrimSurfaceTool Trim(Bis, F[0], F[1],
                // E[0], E[2], Inv0[0], Inv1[0])`.
                let trim = TrimSurfaceTool::new(
                    bis.clone(),
                    f0.clone(),
                    f1.clone(),
                    e0.clone(),
                    e2.clone(),
                    inv0[0],
                    inv1[0],
                );

                // `cxx:815-826`.
                let (node1, node2) = if reverse {
                    (arc.second_node(), arc.first_node())
                } else {
                    (arc.first_node(), arc.second_node())
                };
                let mut node1 =
                    node1.ok_or_else(|| "BRepFill_Evolved: arc without first node".to_string())?;
                let node2 =
                    node2.ok_or_else(|| "BRepFill_Evolved: arc without second node".to_string())?;

                // `cxx:829-839`: a node lying on a spine vertex is replaced by
                // the first node of the arc that starts at the other element.
                let on_basic_elt = graph.node_by_id(node1).on_basic_elt();
                if on_basic_elt {
                    let replacement = if s0.shape_type() == ShapeType::Vertex {
                        arc.first_element()
                            .and_then(|be| graph.basic_elt_by_id(be).start_arc())
                            .and_then(|a| graph.arc_by_id(a).first_node())
                    } else if s1.shape_type() == ShapeType::Vertex {
                        arc.second_element()
                            .and_then(|be| graph.basic_elt_by_id(be).start_arc())
                            .and_then(|a| graph.arc_by_id(a).first_node())
                    } else {
                        None
                    };
                    if let Some(n) = replacement {
                        node1 = n;
                    }
                }

                // `cxx:841-845`.
                let (start_on_f, vs) = vertex_from_node(
                    node1,
                    graph.node_by_id(node1),
                    &prof_edge.0,
                    &vf,
                    &vl,
                    &mut map_node_vertex,
                );
                let (end_on_f, ve) = vertex_from_node(
                    node2,
                    graph.node_by_id(node2),
                    &prof_edge.0,
                    &vf,
                    &vl,
                    &mut map_node_vertex,
                );

                // `cxx:850-910`.
                if !map_seq_ver.is_bound(&vf.0) {
                    if inv0[0] || inv1[0] {
                        par_on_f.clear();
                        v_on_f.clear();
                    } else {
                        par_on_f = trim.intersect_with(&e0, &e2).map_err(|e| format!("{e:?}"))?;
                        v_on_f = par_on_f.iter().map(|_| Vertex::new().0).collect();
                        if let Some(first) = v_on_f.first_mut() {
                            if start_on_f == 1 {
                                if let Some(vs) = vs.as_ref() {
                                    *first = vs.0.clone();
                                }
                            }
                        }
                        if let Some(last) = v_on_f.last_mut() {
                            if end_on_f == 1 {
                                if let Some(ve) = ve.as_ref() {
                                    *last = ve.0.clone();
                                }
                            }
                        }
                    }
                } else {
                    par_on_f = map_seq_par.find(&vf.0).cloned().unwrap_or_default();
                    v_on_f = map_seq_ver.find(&vf.0).cloned().unwrap_or_default();
                }

                if !map_seq_ver.is_bound(&vl.0) {
                    if inv0[1] || inv1[1] {
                        par_on_l.clear();
                        v_on_l.clear();
                    } else {
                        par_on_l = trim.intersect_with(&e1, &e3).map_err(|e| format!("{e:?}"))?;
                        v_on_l = par_on_l.iter().map(|_| Vertex::new().0).collect();
                        if let Some(first) = v_on_l.first_mut() {
                            if start_on_f == 3 {
                                if let Some(vs) = vs.as_ref() {
                                    *first = vs.0.clone();
                                }
                            }
                        }
                        if let Some(last) = v_on_l.last_mut() {
                            if end_on_f == 3 {
                                if let Some(ve) = ve.as_ref() {
                                    *last = ve.0.clone();
                                }
                            }
                        }
                    }
                } else {
                    par_on_l = map_seq_par.find(&vl.0).cloned().unwrap_or_default();
                    v_on_l = map_seq_ver.find(&vl.0).cloned().unwrap_or_default();
                }

                // `cxx:919-930`.
                if start_on_f == 0 && end_on_f == 0 && v_on_l.is_empty() && v_on_f.is_empty() {
                    prof_exp.next();
                    continue;
                }
                if start_on_f == 0 && end_on_f == 0 && v_on_l.len() + v_on_f.len() == 1 {
                    prof_exp.next();
                    continue;
                }

                // `cxx:939-950`.
                let intervals = compute_intervals(
                    &v_on_f,
                    &v_on_l,
                    &par_on_f,
                    &par_on_l,
                    &trim,
                    &bis,
                    vs.as_ref().map(|v| &v.0),
                    ve.as_ref().map(|v| &v.0),
                );

                // `cxx:952-1010`.
                for ti in 0..intervals.first_par.len() {
                    let v1 = Vertex(intervals.first_v[ti].clone());
                    let v2 = Vertex(intervals.last_v[ti].clone());

                    let (cbis, pc1, pc2, continuity) = trim
                        .project(intervals.first_par[ti], intervals.last_par[ti])
                        .map_err(|e| format!("{e:?}"))?;

                    // `cxx:965-972`.
                    let mut current_edge = builder.make_edge(
                        cbis.clone(),
                        cbis.first_parameter(),
                        cbis.last_parameter(),
                    );
                    update_vertex_point(&v1, &cbis.d0(cbis.first_parameter()), FILL_CONFUSION);
                    update_vertex_point(&v2, &cbis.d0(cbis.last_parameter()), FILL_CONFUSION);
                    builder.add(&mut current_edge.0, &v1.0.oriented(Orientation::Forward));
                    builder.add(&mut current_edge.0, &v2.0.oriented(Orientation::Reversed));
                    registry.set_ranges_all(
                        &current_edge.0,
                        cbis.first_parameter(),
                        cbis.last_parameter(),
                    );
                    registry.set_edge_pcurve(
                        &current_edge.0,
                        GeometryRegistry::shape_key(&f0.0),
                        pc1,
                    );
                    registry.set_edge_pcurve(
                        &current_edge.0,
                        GeometryRegistry::shape_key(&f1.0),
                        pc2,
                    );
                    // `cxx:977`: `Continuity(CurrentEdge, F[0], F[1], Cont)`.
                    crate::brep_lib_continuity::set_stored_continuity(
                        &current_edge,
                        &f0,
                        &f1,
                        shape_to_u8(continuity),
                    );

                    // `cxx:982-987`.
                    map_bis.entry_or_bind(&f0.0, Vec::new);
                    map_bis.entry_or_bind(&f1.0, Vec::new);

                    // `cxx:993-1009`.
                    let o0 = ori_edge_in_face(&e0, &f0)?;
                    let o2 = ori_edge_in_face(&e2, &f1)?;
                    if distance_to_oz(&vf) < distance_to_oz(&vl) {
                        map_bis
                            .entry_or_bind(&f0.0, Vec::new)
                            .push(current_edge.0.oriented(o0));
                        let mut second = current_edge.0.clone();
                        second.set_orientation(o2.complement());
                        map_bis.entry_or_bind(&f1.0, Vec::new).push(second);
                    } else {
                        map_bis
                            .entry_or_bind(&f1.0, Vec::new)
                            .push(current_edge.0.oriented(o2));
                        let mut second = current_edge.0.clone();
                        second.set_orientation(o0.complement());
                        map_bis.entry_or_bind(&f0.0, Vec::new).push(second);
                    }
                }

                // `cxx:1016-1072`: the vertices on the parallel edges.
                for k in [0usize, 2] {
                    if map_seq_ver.is_bound(&vf.0) {
                        continue;
                    }
                    if v_on_f.is_empty() {
                        continue;
                    }
                    let e = if k == 0 { &e0 } else { &e2 };
                    map_bis.entry_or_bind(&e.0, Vec::new);
                    map_ver_par.entry_or_bind(&e.0, Vec::new);
                    for (ii, v) in v_on_f.iter().enumerate() {
                        map_bis.entry_or_bind(&e.0, Vec::new).push(v.clone());
                        let par = if k == 0 {
                            par_on_f[ii].y()
                        } else {
                            par_on_f[ii].z()
                        };
                        map_ver_par.entry_or_bind(&e.0, Vec::new).push(par);
                    }
                }
                for k in [1usize, 3] {
                    if map_seq_ver.is_bound(&vl.0) {
                        continue;
                    }
                    if v_on_l.is_empty() {
                        continue;
                    }
                    let e = if k == 1 { &e1 } else { &e3 };
                    map_bis.entry_or_bind(&e.0, Vec::new);
                    map_ver_par.entry_or_bind(&e.0, Vec::new);
                    for (ii, v) in v_on_l.iter().enumerate() {
                        map_bis.entry_or_bind(&e.0, Vec::new).push(v.clone());
                        let par = if k == 1 {
                            par_on_l[ii].y()
                        } else {
                            par_on_l[ii].z()
                        };
                        map_ver_par.entry_or_bind(&e.0, Vec::new).push(par);
                    }
                }

                // `cxx:1078-1082`.
                map_seq_par.bind(&vf.0, par_on_f.clone());
                map_seq_ver.bind(&vf.0, v_on_f.clone());
                map_seq_par.bind(&vl.0, par_on_l.clone());
                map_seq_ver.bind(&vl.0, v_on_l.clone());

                prof_exp.next();
            }
        }

        // `cxx:1095-1191`: parallel edges on the profile vertices.
        let spine_keys: Vec<TopoShape> = self.my_map.keys().cloned().collect();
        for current_spine in &spine_keys {
            let mut prec_prof: Option<TopoShape> = None;
            let mut current_prof: Option<TopoShape> = None;

            let mut prof_exp = WireExplorer::new();
            prof_exp.init(&my_profile, None);
            while prof_exp.more() {
                let Some(prof) = prof_exp.current().cloned() else {
                    break;
                };
                current_prof = Some(prof.0.clone());
                let (vcf, _) = edge_vertices_oriented(&prof);
                let Some(vcf) = vcf else {
                    prof_exp.next();
                    continue;
                };
                let Some(current_edge_shape) = first_of(&self.my_map, current_spine, &vcf.0) else {
                    prof_exp.next();
                    continue;
                };
                let current_edge = Edge(current_edge_shape);

                if map_bis.is_bound(&current_edge.0) {
                    // `cxx:1121-1138`: the control face must be one of the
                    // faces of the volevo.
                    let mut face_controle = first_of(&self.my_map, current_spine, &prof.0);
                    let mut ya_face = face_controle.is_some();
                    if !ya_face {
                        if let Some(prec) = prec_prof.as_ref() {
                            face_controle = first_of(&self.my_map, current_spine, prec);
                            ya_face = face_controle
                                .as_ref()
                                .map(|f| map_bis.is_bound(f))
                                .unwrap_or(false);
                        }
                    } else {
                        ya_face = face_controle
                            .as_ref()
                            .map(|f| map_bis.is_bound(f))
                            .unwrap_or(false);
                    }

                    if ya_face {
                        if let Some(face_controle) = face_controle {
                            let edges_controle =
                                map_bis.find(&face_controle).cloned().unwrap_or_default();
                            let mut the_ver =
                                map_bis.find(&current_edge.0).cloned().unwrap_or_default();
                            let mut the_par =
                                map_ver_par.find(&current_edge.0).cloned().unwrap_or_default();
                            let shape = trim_edge(
                                &current_edge,
                                &edges_controle,
                                &mut the_ver,
                                &mut the_par,
                            );
                            self.my_map
                                .list_mut(current_spine, &vcf.0)
                                .extend(shape);
                        }
                    }
                }

                prec_prof = current_prof.clone();
                prof_exp.next();
            }

            // `cxx:1161-1189`: the parallel edge of the last profile vertex.
            let vcl = {
                let mut exp = WireExplorer::new();
                exp.init(&my_profile, None);
                let mut last_edge: Option<Edge> = None;
                while exp.more() {
                    if let Some(e) = exp.current() {
                        last_edge = Some(e.clone());
                    }
                    exp.next();
                }
                last_edge.and_then(|e| edge_vertices_oriented(&e).1)
            };
            if let Some(vcl) = vcl {
                if let Some(current_edge_shape) = first_of(&self.my_map, current_spine, &vcl.0) {
                    let current_edge = Edge(current_edge_shape);
                    if map_bis.is_bound(&current_edge.0) {
                        let mut ya_face = true;
                        let mut face_controle =
                            current_prof.and_then(|p| first_of(&self.my_map, current_spine, &p));
                        match face_controle.as_ref() {
                            Some(f) if map_bis.is_bound(f) => {}
                            _ => ya_face = false,
                        }
                        let extent = self
                            .my_map
                            .list(current_spine, &vcl.0)
                            .map(|l| l.len())
                            .unwrap_or(0);
                        if ya_face && extent <= 1 {
                            if let Some(face_controle) = face_controle.take() {
                                let edges_controle =
                                    map_bis.find(&face_controle).cloned().unwrap_or_default();
                                let mut the_ver =
                                    map_bis.find(&current_edge.0).cloned().unwrap_or_default();
                                let mut the_par = map_ver_par
                                    .find(&current_edge.0)
                                    .cloned()
                                    .unwrap_or_default();
                                let shape = trim_edge(
                                    &current_edge,
                                    &edges_controle,
                                    &mut the_ver,
                                    &mut the_par,
                                );
                                self.my_map
                                    .list_mut(current_spine, &vcl.0)
                                    .extend(shape);
                            }
                        }
                    }
                }
            }
        }

        // `cxx:1195-1262`: cut the faces by the collected edges.
        for current_spine in &spine_keys {
            let mut prof_exp = WireExplorer::new();
            prof_exp.init(&my_profile, None);
            while prof_exp.more() {
                let Some(prof_edge) = prof_exp.current().cloned() else {
                    break;
                };
                let Some(face_shape) = first_of(&self.my_map, current_spine, &prof_edge.0) else {
                    prof_exp.next();
                    continue;
                };
                let current_face = Face(face_shape);
                self.my_map.list_mut(current_spine, &prof_edge.0).clear();

                if map_bis.is_bound(&current_face.0) {
                    // `cxx:1218`: the edges of the two parallel lists are
                    // appended to the cut list, oriented in the face.
                    let (vcf, vcl) = edge_vertices_oriented(&prof_edge);
                    if let Some(vcf) = vcf.as_ref() {
                        let lf = self
                            .my_map
                            .list(current_spine, &vcf.0)
                            .cloned()
                            .unwrap_or_default();
                        if let Some(first) = lf.first() {
                            let ori = ori_edge_in_face(&Edge(first.clone()), &current_face)?;
                            for (idx, s) in lf.iter().enumerate() {
                                if idx == 0 {
                                    continue;
                                }
                                map_bis
                                    .entry_or_bind(&current_face.0, Vec::new)
                                    .push(s.oriented(ori));
                            }
                        }
                    }
                    if let Some(vcl) = vcl.as_ref() {                        let ll = self
                            .my_map
                            .list(current_spine, &vcl.0)
                            .cloned()
                            .unwrap_or_default();
                        if let Some(first) = ll.first() {
                            let ori = ori_edge_in_face(&Edge(first.clone()), &current_face)?;
                            for (idx, s) in ll.iter().enumerate() {
                                if idx == 0 {
                                    continue;
                                }
                                map_bis
                                    .entry_or_bind(&current_face.0, Vec::new)
                                    .push(s.oriented(ori));
                            }
                        }
                    }

                    // `cxx:1237-1239`.
                    let mut cut_edges = map_bis
                        .find(&current_face.0)
                        .cloned()
                        .unwrap_or_default();
                    let faces = trim_face(&current_face, &mut cut_edges);

                    // `cxx:1241-1244`.
                    if let Some(shape) = self.my_shape.as_mut() {
                        for f in &faces {
                            builder.add(shape, f);
                        }
                    }
                    self.my_map
                        .list_mut(current_spine, &prof_edge.0)
                        .extend(faces);
                }

                prof_exp.next();
            }

            // `cxx:1252-1260`: drop the first (origin) edge from the lists of
            // the profile vertices.
            let mut seen: Vec<usize> = Vec::new();
            for v in vertices_of(&my_profile.0) {
                let key = GeometryRegistry::shape_key(&v.0);
                if seen.contains(&key) {
                    continue;
                }
                seen.push(key);
                let list = self.my_map.list_mut(current_spine, &v.0);
                if !list.is_empty() {
                    list.remove(0);
                }
            }
        }

        self.my_is_done = true;
        Ok(())
    }
}

/// `GeomAbs_Shape` as its OCCT integer (`GeomAbs_Shape.hxx`), the encoding
/// `BRep_Tool::Continuity` stores.
fn shape_to_u8(s: Shape) -> u8 {
    match s {
        Shape::C0 => 0,
        Shape::G1 => 1,
        Shape::C1 => 2,
        Shape::G2 => 3,
        Shape::C2 => 4,
        Shape::C3 => 5,
        Shape::CN => 6,
    }
}
